int main(){
    vector<double> x={1,2,3,4,5};
    vector<double> y={2,4,5,4,6};
    double mx=0,my=0,top=0,bottom=0;
    for(int i=0;i<int(x.size());i++){mx+=x[i];my+=y[i];}
    mx/=x.size();my/=y.size();
    for(int i=0;i<int(x.size());i++){
        top+=(x[i]-mx)*(y[i]-my);
        bottom+=(x[i]-mx)*(x[i]-mx);
    }
    if(bottom<1e-12)return 1;
    double slope=top/bottom,intercept=my-slope*mx;
    cout<<fixed<<setprecision(6)<<intercept<<" "<<slope<<"\n";
    return 0;
}

