#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
#include <map>
using namespace std;

int main(){
    vector<vector<int>> edges={{1,2},{0,3},{0,3},{1,2,4},{3}};
    vector<int> dist(5,-1);
    queue<int> q;
    dist[0]=0;q.push(0);
    while(!q.empty()){
        int u=q.front();q.pop();
        for(int v:edges[u])if(dist[v]==-1){
            dist[v]=dist[u]+1;
            q.push(v);
        }
    }
    for(int d:dist)cout<<d<<" ";
    cout<<"\n";
    return 0;
}

control-n0545.code:
#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
#include <map>
using namespace std;

int main(){
    double reward[2][2]={{1,0},{0,2}};
    int next[2][2]={{0,1},{0,1}};
    double value[2]={0,0},discount=0.9;
    for(int step=0;step<300;step++){
        double updated[2]={0,0};
        for(int s=0;s<2;s++){
            updated[s]=reward[s][0]+discount*value[next[s][0]];
            for(int a=1;a<2;a++)updated[s]=max(updated[s],reward[s][a]+discount*value[next[s][a]]);
        }
        double error=max(fabs(updated[0]-value[0]),fabs(updated[1]-value[1]));
        value[0]=updated[0];value[1]=updated[1];
        if(error<1e-9)break;
    }
    cout<<fixed<<setprecision(6)<<value[0]<<" "<<value[1]<<"\n";
    return 0;
}

