using namespace std;

int main(){
    vector<double> x={-2,-1,0,1,4};
    double mean=0,m2=0,m3=0,m4=0;
    for(double z:x)mean+=z;
    mean/=x.size();
    for(double z:x){
        double d=z-mean;
        m2+=d*d;m3+=d*d*d;m4+=d*d*d*d;
    }
    m2/=x.size();m3/=x.size();m4/=x.size();
    if(m2<=0)return 1;
    cout<<fixed<<setprecision(6)<<m3/pow(m2,1.5)<<" "<<m4/(m2*m2)-3<<"\n";
    return 0;
}
